diff --git a/nix/orca-mac-keybindings-merge.js b/nix/orca-mac-keybindings-merge.js
new file mode 100644
index 00000000..0f5f2de2
--- /dev/null
+++ b/nix/orca-mac-keybindings-merge.js
@@ -0,0 +1,151 @@
+// Merges the generated overrides (orca-mac-keybindings.js) into
+// ~/.orca/keybindings.json's platforms.linux. See orca.nix.
+//
+//   node orca-mac-keybindings-merge.js <app>/out/shared <owned.json>
+//
+// The file is Orca's read-write state, so this owns only what it wrote: a
+// sidecar, keybindings.nix-owned.json, records the values of the last write.
+//   - a key written last time and no longer generated is removed;
+//   - a key whose value the UI has changed since is left as the UI's;
+//   - everything else in the file is untouched.
+// Then the merged file gets Orca's own conflict check. Orca drops every
+// action in a conflicting set at load, so a generated key that clashes with
+// a UI shortcut is withdrawn instead, and named, leaving the UI's choice and
+// the generated action's Linux default.
+const fs = require('fs');
+const os = require('os');
+const path = require('path');
+
+// Activation runs under set -e, so a throw here would abandon the rest of
+// the switch over a keybinding file. Any failure is one line and exit 0;
+// the file is then exactly as it was, since writes only ever rename over it.
+process.on('uncaughtException', (e) => {
+  console.error(`orca: keybinding merge skipped: ${e.message}`);
+  process.exit(0);
+});
+
+const [shared, ownedFile] = process.argv.slice(2);
+const kb = require(path.resolve(shared, 'keybindings.js'));
+const owned = JSON.parse(fs.readFileSync(ownedFile, 'utf8'));
+
+const dir = path.join(os.homedir(), '.orca');
+const dest = path.join(dir, 'keybindings.json');
+const sidecar = path.join(dir, 'keybindings.nix-owned.json');
+const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
+const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
+
+// Orca's own writer (G$): whole file to a temp name, rename over, and the
+// temp removed if either step fails.
+function writeJson(file, value) {
+  const tmp = `${file}.nix-${process.pid}-${Date.now()}`;
+  try {
+    fs.writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`, { flag: 'wx' });
+    fs.renameSync(tmp, file);
+  } catch (e) {
+    fs.rmSync(tmp, { force: true });
+    throw e;
+  }
+}
+
+fs.mkdirSync(dir, { recursive: true });
+let doc;
+if (!fs.existsSync(dest)) {
+  doc = { version: 1, keybindings: {}, platforms: { darwin: {}, linux: {}, win32: {} } };
+} else {
+  let why = null;
+  try {
+    doc = JSON.parse(fs.readFileSync(dest, 'utf8'));
+    if (!isObject(doc)) why = 'not a JSON object';
+  } catch (e) {
+    why = e.message;
+  }
+  if (why !== null) {
+    // Orca's loader rejects it too and says so; overwriting would lose
+    // whatever the user was halfway through editing.
+    console.error(`orca: ${dest}: ${why}; leaving it for Orca to report`);
+    process.exit(0);
+  }
+}
+
+let prev = {};
+try {
+  const s = JSON.parse(fs.readFileSync(sidecar, 'utf8'));
+  if (!isObject(s?.linux)) throw new Error('no .linux object');
+  prev = s.linux;
+} catch (e) {
+  // No sidecar is a first run. A bad one stops the merge: it decides what
+  // may be overwritten, and reading it as empty overwrites every key the UI
+  // has changed.
+  if (e.code !== 'ENOENT') {
+    console.error(`orca: ${sidecar}: ${e.message}; not merging -- delete it to start over`);
+    process.exit(0);
+  }
+}
+
+const platforms = isObject(doc.platforms) ? doc.platforms : {};
+const linux = isObject(platforms.linux) ? { ...platforms.linux } : {};
+// Changed since the last write: the UI's now. Absent (reset in the UI)
+// is not a change -- the reset target is this table, so it comes back.
+const theirs = new Set(Object.keys(prev).filter((id) => id in linux && !same(linux[id], prev[id])));
+for (const id of Object.keys(prev)) {
+  if (!theirs.has(id)) delete linux[id];
+}
+// What the UI had on each key about to be overwritten, for a withdrawal
+// below to put back. Stale keys are gone by now, so anything left is the UI's.
+const before = {};
+const written = {};
+for (const [id, bindings] of Object.entries(owned)) {
+  if (theirs.has(id)) continue;
+  if (id in linux) before[id] = linux[id];
+  linux[id] = bindings;
+  written[id] = bindings;
+}
+
+// What Orca's loader feeds its conflict pass: common, then the platform
+// section over it, with its string shorthand and null/false expanded.
+// Common is the root's action keys in the legacy shape with no .keybindings.
+const common = doc.keybindings === undefined ? doc : isObject(doc.keybindings) ? doc.keybindings : {};
+const expand = (v) =>
+  v === null || v === false ? [] : typeof v === 'string' ? [v]
+    : Array.isArray(v) && v.every((b) => typeof b === 'string') ? v : undefined;
+const effective = {};
+for (const [id, v] of Object.entries({ ...common, ...linux })) {
+  if (kb.isKeybindingActionId(id) && expand(v) !== undefined) effective[id] = expand(v);
+}
+for (;;) {
+  const withdrawn = kb
+    .findKeybindingConflicts('linux', effective)
+    .flatMap((c) => c.actionIds)
+    .filter((id) => id in written);
+  // Only generated keys are ever withdrawn. A conflict with none left in it
+  // -- between UI shortcuts, or a UI shortcut and the Linux default a
+  // withdrawal brought back -- is Orca's to report.
+  if (withdrawn.length === 0) break;
+  for (const id of new Set(withdrawn)) {
+    console.error(`orca: ${id} ${JSON.stringify(written[id])} clashes with a shortcut set in Orca; keeping that one`);
+    delete written[id];
+    if (id in before) {
+      linux[id] = before[id];
+    } else {
+      delete linux[id];
+    }
+    const fallback = id in linux ? linux[id] : common[id];
+    if (kb.isKeybindingActionId(id) && expand(fallback) !== undefined) effective[id] = expand(fallback);
+    else delete effective[id];
+  }
+}
+
+doc.version = 1;
+doc.platforms = {
+  ...platforms,
+  darwin: isObject(platforms.darwin) ? platforms.darwin : {},
+  linux,
+  win32: isObject(platforms.win32) ? platforms.win32 : {},
+};
+writeJson(dest, doc);
+// Every key this table claims, written or withdrawn, at its generated value;
+// the UI's keep the value last written. Either way a later UI value reads as
+// changed, the UI's, rather than as never owned and free to overwrite.
+writeJson(sidecar, {
+  linux: { ...Object.fromEntries([...theirs].map((id) => [id, prev[id]])), ...owned, ...written },
+});
diff --git a/nix/orca-mac-keybindings.js b/nix/orca-mac-keybindings.js
new file mode 100644
index 00000000..133c70b7
--- /dev/null
+++ b/nix/orca-mac-keybindings.js
@@ -0,0 +1,64 @@
+// Emits Orca's platforms.linux keybinding overrides: every action's macOS
+// default, with Mod (Cmd there, Ctrl here) spelled Cmd, which Orca binds to
+// Super on Linux. See orca.nix.
+//
+//   node orca-mac-keybindings.js <app>/out/shared <hyprland-chords.json>
+//
+// Uses Orca's own keybinding module (out/shared/keybindings.js, the stable
+// facade its comment promises) for the definitions, normalisation and the
+// conflict check, so a version bump regenerates the table instead of
+// silently drifting from it.
+const fs = require('fs');
+const path = require('path');
+
+const [shared, chordsFile] = process.argv.slice(2);
+const kb = require(path.resolve(shared, 'keybindings.js'));
+
+// Chords Hyprland binds never reach the window. "SUPER + SHIFT + W" ->
+// "Cmd+Shift+W". Mouse, switch and media-key binds cannot be an Orca chord;
+// anything else that does not translate is an error, not a free chord.
+const MODS = { SUPER: 'Cmd', CTRL: 'Ctrl', CONTROL: 'Ctrl', ALT: 'Alt', SHIFT: 'Shift' };
+const KEYS = { return: 'Enter', left: 'ArrowLeft', right: 'ArrowRight', up: 'ArrowUp', down: 'ArrowDown' };
+const taken = new Set();
+for (const chord of JSON.parse(fs.readFileSync(chordsFile, 'utf8'))) {
+  const parts = chord.split('+').map((s) => s.trim());
+  const key = parts.pop();
+  if (/^(mouse[:_]|XF86)/.test(key) || chord.startsWith('switch:')) continue;
+  const mods = parts.map((p) => MODS[p.toUpperCase()]);
+  const n = mods.every(Boolean) && kb.normalizeKeybinding([...mods, KEYS[key] ?? key].join('+'));
+  if (!n || !n.ok) throw new Error(`cannot translate Hyprland bind "${chord}" to an Orca chord`);
+  taken.add(n.value);
+}
+// A digit-index action's one binding stands for its whole 1-9 family.
+const isTaken = (id, binding) =>
+  kb.isDigitIndexActionId(id)
+    ? [1, 2, 3, 4, 5, 6, 7, 8, 9].some((d) => taken.has(binding.replace(/1$/, String(d))))
+    : taken.has(binding);
+
+const overrides = {};
+for (const def of kb.KEYBINDING_DEFINITIONS) {
+  const mac = kb.getDefaultBindings(def, 'darwin').map((binding) => {
+    const cmd = binding.split('+').map((t) => (t === 'Mod' ? 'Cmd' : t)).join('+');
+    const n = kb.normalizeKeybindingWithOptions(cmd, kb.normalizeOptionsForAction(def.id));
+    if (!n.ok) throw new Error(`${def.id}: ${cmd}: ${n.error}`);
+    return n.value;
+  });
+  const free = mac.filter((b) => !isTaken(def.id, b));
+  if (free.length < mac.length) {
+    console.error(`${def.id}: ${mac.filter((b) => isTaken(def.id, b)).join(', ')} is Hyprland's`);
+  }
+  // Every chord taken: leave the action on its Linux default rather than
+  // unbinding it. No macOS binding at all is different -- unbound there, so
+  // unbound here ([]). Same as the Linux default: nothing to say.
+  if (mac.length > 0 && free.length === 0) continue;
+  if (JSON.stringify(free) === JSON.stringify(kb.getDefaultBindings(def, 'linux'))) continue;
+  overrides[def.id] = free;
+}
+
+// Orca drops every action in a conflicting set at load, with only a line in
+// its diagnostics; fail the build instead.
+const conflicts = kb.findKeybindingConflicts('linux', overrides);
+if (conflicts.length > 0) {
+  throw new Error(`conflicting shortcuts: ${JSON.stringify(conflicts)}`);
+}
+process.stdout.write(`${JSON.stringify(overrides, null, 2)}\n`);
diff --git a/orca.nix b/orca.nix
index 72e5e26b..37a43814 100644
--- a/orca.nix
+++ b/orca.nix
@@ -89,6 +89,49 @@ let
   # Extracted once, shared by the wrapper's extraInstallCommands below;
   # let bindings are recursive, so position in the block does not matter.
   appimageContents = pkgs.appimageTools.extract { inherit pname version src; };
+
+  # Mac-style shortcuts, the same Super-for-Cmd scheme as gtk's mac-bindings
+  # and ghostty's super+c/v in home.nix: Orca's own macOS defaults, with Cmd
+  # spelled out, which Orca binds to Super (event.metaKey) on Linux. Ctrl then
+  # goes back to the terminal: Ctrl+C is SIGINT again, not copy. Except where
+  # the Mac table itself says Ctrl: Ctrl+1..9 selects a tab (Linux: Alt+1..9),
+  # Ctrl+Tab and Ctrl+PageUp/Down cycle them, as on a Mac.
+  #
+  # Generated from the app's own keybinding definitions at build time
+  # (nix/orca-mac-keybindings.js), so a version bump picks up new actions.
+  # Chords Hyprland binds are skipped and those actions keep their Linux Ctrl
+  # default -- the compositor would eat them, leaving a dead key. That costs
+  # Super+F (find), Super+P (go to file), Super+N and Super+B, which are
+  # Hyprland's emacs-style focus moves; the build log lists every one.
+  hyprlandChords = let s = config.wayland.windowManager.hyprland.settings; in
+    lib.concatMap
+      (k: map (b: if builtins.isAttrs b && b ? _args then builtins.head b._args else b) s.${k})
+      (builtins.filter (lib.hasPrefix "bind") (builtins.attrNames s));
+  macKeybindings = pkgs.runCommand "orca-mac-keybindings" {
+    nativeBuildInputs = [ pkgs.nodejs pkgs.asar pkgs.makeWrapper ];
+  } ''
+    asar extract ${appimageContents}/resources/app.asar app
+    mkdir -p $out/share $out/bin
+    node ${./nix/orca-mac-keybindings.js} app/out/shared \
+      ${pkgs.writeText "hyprland-chords.json" (builtins.toJSON hyprlandChords)} \
+      > $out/share/orca-mac-keybindings.json
+    # The merge runs Orca's conflict check on the merged file at activation,
+    # so the keybinding module (and its one sibling import) ships alongside.
+    mkdir -p $out/lib/shared
+    cp -r app/out/shared/keybindings.js app/out/shared/keybindings \
+      app/out/shared/tui-agent-display-names.js $out/lib/shared/
+    # An Orca bump that adds an import fails here, not at activation.
+    node -e "require('$out/lib/shared/keybindings.js')"
+    makeWrapper ${pkgs.nodejs}/bin/node $out/bin/orca-mac-keybindings \
+      --add-flags "${./nix/orca-mac-keybindings-merge.js} $out/lib/shared $out/share/orca-mac-keybindings.json"
+  '';
+  # ~/.orca/keybindings.json is Orca's read-write state: its settings UI saves
+  # into the same platforms.linux section, by atomic rename, so a home.file
+  # symlink would be replaced on the first edit. So the generated keys are
+  # merged into whatever Orca last wrote, owning only what the last merge
+  # wrote (a sidecar records it), and a UI edit outranks them -- the rules
+  # are at the top of nix/orca-mac-keybindings-merge.js.
+  # tests/orca-mac-keybindings.sh.
 in
 {
   home.packages =
@@ -98,4 +141,9 @@ in
     # same reason parsec gets it.
       (config.lib.nixGL.wrap orca)
     ];
+
+  home.activation.orcaMacKeybindings = lib.mkIf (!isDarwin && isDesktop)
+    (lib.hm.dag.entryAfter [ "writeBoundary" ] ''
+      $DRY_RUN_CMD ${macKeybindings}/bin/orca-mac-keybindings
+    '');
 }
diff --git a/tests/orca-mac-keybindings.sh b/tests/orca-mac-keybindings.sh
new file mode 100755
index 00000000..cf1c744f
--- /dev/null
+++ b/tests/orca-mac-keybindings.sh
@@ -0,0 +1,193 @@
+#!/usr/bin/env bash
+# Cases for orca.nix's Mac-style keybindings: Orca's own macOS defaults, with
+# Cmd on Super, merged into ~/.orca/keybindings.json at activation.
+#
+# Two contracts, both silent when broken:
+#
+#   * **No chord Hyprland owns.** The compositor eats a bound chord before the
+#     window sees it, so a Super+F override is not "find", it is a dead key that
+#     also hides Orca's working Ctrl+F default. The generator drops those and
+#     leaves the action on its Linux default; cases 2-3 pin that against the
+#     live Hyprland bind list, not a copy of it.
+#
+#   * **The merge owns only its keys.** Orca's settings UI writes into the same
+#     platforms.linux section, so replacing the section would wipe every
+#     shortcut set in the UI at each switch. Cases 5-6.
+#
+# The merge runs on a throwaway HOME, never the real ~/.orca.
+#
+#   tests/orca-mac-keybindings.sh                   evaluate + build, then test
+#   tests/orca-mac-keybindings.sh <merge-package>   test a given build
+set -u
+set -o pipefail
+
+fails=0; n=0
+pass() { n=$((n+1)); echo "ok   $1"; }
+fail() { n=$((n+1)); echo "FAIL $1: $2"; fails=$((fails+1)); }
+
+FLAKE=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
+HM="$FLAKE#homeConfigurations.$(hostname).config"
+
+PKG="${1:-}"
+if [ -z "$PKG" ]; then
+  # The activation entry's string context names the merge package's drv.
+  drv=$(nix eval --raw "$HM.home.activation.orcaMacKeybindings.data" \
+    --apply 'd: builtins.head (builtins.attrNames (builtins.getContext d))' 2>/dev/null) \
+    || { echo "no home.activation.orcaMacKeybindings on this host" >&2; exit 1; }
+  PKG=$(nix-store --realise "$drv" | tail -1) || { echo "could not build $drv" >&2; exit 1; }
+fi
+MERGE="$PKG/bin/orca-mac-keybindings"
+OWNED="$PKG/share/orca-mac-keybindings.json"
+[ -x "$MERGE" ] && [ -f "$OWNED" ] || { echo "$PKG lacks bin/ or share/" >&2; exit 1; }
+
+T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
+jqo() { jq -c "$1" "$OWNED"; }
+
+# 1. The Mac table, on Super: clipboard and tabs are the reason this exists.
+for c in 'terminal.copySelection:["Cmd+C"]' 'terminal.paste:["Cmd+V"]' \
+         'tab.close:["Cmd+W"]' 'tab.newTerminal:["Cmd+T"]'; do
+  id=${c%%:*}; want=${c#*:}
+  got=$(jqo ".[\"$id\"]")
+  [ "$got" = "$want" ] && pass "$id = $want" || fail "$id" "got $got, want $want"
+done
+got=$(jqo '[.[][] | select(test("(^|\\+)Mod\\+"))]')
+[ "$got" = "[]" ] && pass "no Mod (= Ctrl on Linux) left" || fail "Mod" "still bound: $got"
+
+# 2. Nothing the generator emits is a Hyprland chord.
+nix eval --json "$HM.wayland.windowManager.hyprland.settings" --apply \
+  's: builtins.concatMap (k: map (b: if builtins.isAttrs b && b ? _args then builtins.head b._args else b) s.${k})
+      (builtins.filter (k: builtins.substring 0 4 k == "bind") (builtins.attrNames s))' \
+  2>/dev/null > "$T/hypr.json" || { echo "could not evaluate Hyprland binds" >&2; exit 1; }
+# Hyprland "SUPER + SHIFT + W" -> Orca "Cmd+Shift+W"; letters upper-cased, the
+# keys Orca spells differently renamed. Mouse and switch binds never match.
+jq -r '.[] | split(" + ") | map(
+    {SUPER:"Cmd",CTRL:"Ctrl",ALT:"Alt",SHIFT:"Shift",
+     return:"Enter",left:"ArrowLeft",right:"ArrowRight",up:"ArrowUp",down:"ArrowDown",
+     space:"Space",semicolon:"Semicolon"}[.] // (if length == 1 then ascii_upcase else . end))
+  | join("+")' "$T/hypr.json" | sort -u > "$T/hypr.txt"
+grep -qx 'Cmd+F' "$T/hypr.txt" || { echo "Hyprland bind list lacks Super+F; harness is broken" >&2; exit 1; }
+jq -r '.[][]' "$OWNED" | sort -u > "$T/owned.txt"
+clash=$(comm -12 "$T/hypr.txt" "$T/owned.txt" | tr '\n' ' ')
+[ -z "$clash" ] && pass "no override is a Hyprland chord" || fail "hyprland" "both bind: $clash"
+
+# 3. A chord Hyprland owns leaves its action on Orca's Linux default, not unbound.
+got=$(jqo 'has("editor.find"), has("worktree.quickOpen")' | tr '\n' ' ')
+[ "$got" = "false false " ] && pass "Super+F/Super+P actions keep their Linux defaults" \
+  || fail "fallback" "editor.find/worktree.quickOpen overridden: $got"
+
+# 4. Fresh box: the file is created in the shape Orca writes.
+H="$T/fresh"; mkdir -p "$H"
+HOME=$H "$MERGE" >/dev/null 2>&1
+got=$(jq -c --slurpfile o "$OWNED" '[.version, (.platforms.linux == $o[0]), .keybindings, .platforms.darwin]' "$H/.orca/keybindings.json" 2>/dev/null)
+[ "$got" = '[1,true,{},{}]' ] && pass "fresh HOME gets a version-1 file" || fail "fresh" "got $got"
+cp "$H/.orca/keybindings.json" "$T/first.json"
+HOME=$H "$MERGE" >/dev/null 2>&1
+cmp -s "$T/first.json" "$H/.orca/keybindings.json" && pass "second switch changes nothing" \
+  || fail "idempotent" "re-running the merge rewrote the file"
+
+# 5. Owned keys win; UI edits to other actions, common and darwin survive.
+H="$T/edited"; mkdir -p "$H/.orca"
+cat > "$H/.orca/keybindings.json" <<'EOF'
+{"version":1,"keybindings":{"tab.rename":["Alt+R"]},
+ "platforms":{"darwin":{"tab.close":["Cmd+Q"]},"linux":{"tab.close":["Ctrl+Q"],"editor.find":["Alt+F"]},"win32":{}}}
+EOF
+HOME=$H "$MERGE" >/dev/null 2>&1
+got=$(jq -c '[.platforms.linux["tab.close"], .platforms.linux["editor.find"], .keybindings, .platforms.darwin]' "$H/.orca/keybindings.json")
+[ "$got" = '[["Cmd+W"],["Alt+F"],{"tab.rename":["Alt+R"]},{"tab.close":["Cmd+Q"]}]' ] \
+  && pass "merge keeps UI edits outside its keys" || fail "merge" "got $got"
+
+# 6. A file Orca cannot parse is left alone; activation does not fail on it.
+H="$T/broken"; mkdir -p "$H/.orca"; printf '{not json' > "$H/.orca/keybindings.json"
+if HOME=$H "$MERGE" >/dev/null 2>&1 && [ "$(cat "$H/.orca/keybindings.json")" = '{not json' ] \
+   && [ -z "$(ls "$H/.orca" | grep -v "^keybindings.json$")" ]; then
+  pass "unparseable file untouched, exit 0"
+else
+  fail "broken" "file changed, a temp file left behind, or non-zero exit"
+fi
+
+# 7. A key an earlier generation wrote, and this one no longer emits (Hyprland
+#    took the chord, say), is removed -- unless the UI has changed it since.
+#    A generated key the UI changed after it was written stays the UI's.
+H="$T/stale"; mkdir -p "$H/.orca"
+cat > "$H/.orca/keybindings.json" <<'EOF'
+{"version":1,"keybindings":{},
+ "platforms":{"darwin":{},"linux":{"editor.find":["Cmd+F"],"worktree.quickOpen":["Alt+P"],"tab.close":["Ctrl+Q"]},"win32":{}}}
+EOF
+echo '{"linux":{"editor.find":["Cmd+F"],"worktree.quickOpen":["Cmd+P"],"tab.close":["Cmd+W"]}}' \
+  > "$H/.orca/keybindings.nix-owned.json"
+# Twice: the second run reads the sidecar the first wrote, which must still
+# know the UI's keys as changed rather than as never owned.
+HOME=$H "$MERGE" >/dev/null 2>&1; HOME=$H "$MERGE" >/dev/null 2>&1
+got=$(jq -c '[.platforms.linux["editor.find"], .platforms.linux["worktree.quickOpen"], .platforms.linux["tab.close"]]' "$H/.orca/keybindings.json")
+[ "$got" = '[null,["Alt+P"],["Ctrl+Q"]]' ] && pass "stale generated key dropped, UI-changed ones kept" \
+  || fail "stale" "got $got"
+
+# 8. A UI shortcut on a generated chord: Orca would drop *both* actions at load.
+#    The UI's choice stands; the generated action falls back to its default.
+H="$T/clash"; mkdir -p "$H/.orca"
+cat > "$H/.orca/keybindings.json" <<'EOF'
+{"version":1,"keybindings":{},"platforms":{"darwin":{},"linux":{"tab.newBrowser":["Cmd+T"]},"win32":{}}}
+EOF
+err=$(HOME=$H "$MERGE" 2>&1 >/dev/null)
+got=$(jq -c '[.platforms.linux["tab.newBrowser"], .platforms.linux["tab.newTerminal"]]' "$H/.orca/keybindings.json")
+if [ "$got" = '[["Cmd+T"],null]' ] && [[ $err == *tab.newTerminal* ]]; then
+  pass "UI chord wins a clash, and the dropped key is named"
+else
+  fail "clash" "got $got, stderr '$err'"
+fi
+
+# 8b. A withdrawn key puts back whatever the UI had there, and keeps it on
+#     the next switch, instead of deleting it.
+H="$T/clash-restore"; mkdir -p "$H/.orca"
+cat > "$H/.orca/keybindings.json" <<'EOF'
+{"version":1,"keybindings":{},"platforms":{"darwin":{},"linux":{"tab.newBrowser":["Cmd+T"],"tab.newTerminal":["Alt+N"]},"win32":{}}}
+EOF
+HOME=$H "$MERGE" >/dev/null 2>&1; HOME=$H "$MERGE" >/dev/null 2>&1
